/*
 * A163878  Number of reduced words of length n in Coxeter group on 5
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^6 = I.
 * https://oeis.org/A163878
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = -6*a(n-6) + 3*(a(n-1)+a(n-2)+a(n-3)+a(n-4)+a(n-5)) for n
 *            >= 7, with initial values a(0)=1, a(1)=5, a(2)=20, a(3)=80,
 *            a(4)=320, a(5)=1280, a(6)=5110. (The value a(6) is generated by
 *            the above formula only from n=7 onwards.)
 * Range:     u8 n <= 3, u16 n <= 7, u32 n <= 15, u64 n <= 31, u128 n <= 63,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache of already computed terms */
    static seq_t *cache = NULL;
    static idx_t max_comp = 0;   /* highest index currently computed      */
    static size_t cache_cap = 0; /* allocated capacity (in elements)      */

    /* initial terms up to n = 6 */
    static const seq_t init[7] = {
        (seq_t)1,     /* a(0) */
        (seq_t)5,     /* a(1) */
        (seq_t)20,    /* a(2) */
        (seq_t)80,    /* a(3) */
        (seq_t)320,   /* a(4) */
        (seq_t)1280,  /* a(5) */
        (seq_t)5110   /* a(6) */
    };

    /* first-time initialization */
    if (!cache) {
        cache_cap = 7;  /* store values up to a(6) */
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        for (idx_t i = 0; i < 7; ++i) cache[i] = init[i];
        max_comp = 6;
    }

    /* if the requested index is already available, return it */
    if (n <= max_comp) {
        return cache[n];
    }

    /* enlarge cache if necessary */
    if ((idx_t)(cache_cap) <= n) {
        size_t new_cap = (size_t)(n + 1);
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp) { /* allocation failed; return 0 as a safe fallback */
            return (seq_t)0;
        }
        cache = tmp;
        cache_cap = new_cap;
    }

    /* compute missing terms from max_comp+1 up to n */
    for (idx_t i = max_comp + 1; i <= n; ++i) {
        if (i <= 6) {          /* safety guard – already initialized */
            cache[i] = init[i];
            continue;
        }
        seq_t sum = cache[i-1] + cache[i-2] + cache[i-3] + cache[i-4] + cache[i-5];
        sum *= (seq_t)3;
        sum -= cache[i-6] * (seq_t)6;
        cache[i] = sum;
    }

    max_comp = n;
    return cache[n];
}
